// Differential fuzzer driver: runs the cases generated by recomp/fuzz.py and compares against Unicorn.
// build: tools/fuzz.sh
#include "cpu.h"
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <math.h>

uint8_t *MEM;
int taken;
typedef void (*tfn)(CPU *);
extern const tfn fz_fns[];
extern const int fz_n;
extern const char *fz_text[];

// runtime stubs the generated code may reference
void dispatch(CPU *R, uint32_t t) { (void)R; (void)t; }
void rt_trap(CPU *R, uint32_t eip, const char *w) { (void)R; fprintf(stderr, "trap %x %s\n", eip, w); }
void div_trap(CPU *R, uint32_t eip) { (void)R; (void)eip; }
void rt_cpuid(CPU *R) { (void)R; }
uint64_t rt_rdtsc(void) { return 0; }
volatile int gil_contended;
void gil_yield(void) {}

static uint32_t hash32(uint32_t x) {
    x ^= x >> 16; x *= 0x7feb352d; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16;
    return x;
}
static uint8_t *img; static uint32_t img_base = 0x400000, img_size;

static void load_exe(const char *p) {
    FILE *f = fopen(p, "rb");
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t *b = malloc(n); fread(b, 1, n, f); fclose(f);
    uint32_t pe = *(uint32_t *)(b + 0x3c);
    uint16_t nsec = *(uint16_t *)(b + pe + 6), optsz = *(uint16_t *)(b + pe + 20);
    uint8_t *opt = b + pe + 24;
    img_size = *(uint32_t *)(opt + 56);
    img = calloc(1, img_size);
    memcpy(img, b, *(uint32_t *)(opt + 60));
    uint8_t *sec = opt + optsz;
    for (int i = 0; i < nsec; i++, sec += 40) {
        uint32_t vsz = *(uint32_t *)(sec + 8), va = *(uint32_t *)(sec + 12), rsz = *(uint32_t *)(sec + 16), raw = *(uint32_t *)(sec + 20);
        uint32_t k = rsz < vsz || !vsz ? rsz : vsz;
        memcpy(img + va, b + raw, k);
    }
}

static uint32_t rd(FILE *f) { uint32_t v; fread(&v, 4, 1, f); return v; }

static void dump_flags(uint32_t f, char *o) {
    sprintf(o, "%s%s%s%s%s", f & 1 ? "C" : "-", f & 4 ? "P" : "-", f & 64 ? "Z" : "-", f & 128 ? "S" : "-", f & 2048 ? "O" : "-");
}

int main(int argc, char **argv) {
    load_exe(argv[1]);
    FILE *f = fopen(argv[2], "rb");
    MEM = mmap(NULL, 1ull << 32, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON | MAP_NORESERVE, -1, 0);
    uint32_t ncases = rd(f);
    int fails = 0, total = 0, failed_cases = 0;
    for (uint32_t c = 0; c < ncases; c++) {
        uint32_t tid = rd(f), ncp = rd(f), nst = rd(f);
        uint32_t cps[4];
        for (uint32_t i = 0; i < ncp; i++) cps[i] = rd(f);
        int case_fail = 0;
        for (uint32_t s = 0; s < nst; s++) {
            uint32_t regs[8], flags, seed, npages, pages[16], out[8], ofl, mask, tk, nw;
            for (int i = 0; i < 8; i++) regs[i] = rd(f);
            flags = rd(f);
            double fst[8]; fread(fst, 8, 8, f);
            seed = rd(f); npages = rd(f);
            for (uint32_t i = 0; i < npages; i++) { uint32_t p = rd(f); if (i < 16) pages[i] = p; }
            for (int i = 0; i < 8; i++) out[i] = rd(f);
            ofl = rd(f); mask = rd(f); tk = rd(f); nw = rd(f);
            uint32_t *wa = malloc(nw * 4 + 4); uint8_t *wb = malloc(nw + 1);
            for (uint32_t i = 0; i < nw; i++) { wa[i] = rd(f); fread(&wb[i], 1, 1, f); }
            double fout[8]; fread(fout, 8, 8, f);
            uint32_t fsw = rd(f), fmode = rd(f);
            for (uint32_t i = 0; i < ncp; i++) memcpy(MEM + cps[i], img + (cps[i] - img_base), 4096);
            for (uint32_t i = 0; i < npages && i < 16; i++)
                for (uint32_t k = 0; k < 4096; k++) MEM[pages[i] + k] = (uint8_t)hash32(pages[i] + k + seed * 0x9E3779B9u);
            CPU cpu; memset(&cpu, 0, sizeof cpu);
            CPU *R = &cpu;
            R->eax = regs[0]; R->ecx = regs[1]; R->edx = regs[2]; R->ebx = regs[3];
            R->esp = regs[4]; R->ebp = regs[5]; R->esi = regs[6]; R->edi = regs[7];
            set_flags(R, flags & 0x8d5); R->df = (flags >> 10) & 1; R->fcw = 0x27f;
            for (int i = 0; i < 8; i++) R->st[i] = fst[i];
            R->ftop = 0; R->fsw = 0;
            taken = 0;
            fz_fns[tid](R);
            uint32_t got[8] = {R->eax, R->ecx, R->edx, R->ebx, R->esp, R->ebp, R->esi, R->edi};
            uint32_t gfl = get_flags(R);
            int bad = 0;
            for (int i = 0; i < 8; i++) if (got[i] != out[i]) bad = 1;
            if ((gfl ^ ofl) & mask) bad = 1;
            if ((uint32_t)taken != tk) bad = 1;
            int badmem = 0;
            int fpmem = fmode == 2;   // transcendentals: tolerance in memory too
            for (uint32_t i = 0; i < nw; i++) if (MEM[wa[i]] != wb[i] && !fpmem) badmem = 1;
            bad |= badmem;
            int badfp = 0;
            if (fmode) {
                for (int i = 0; i < 8; i++) {
                    double a = R->st[i], b = fout[i];
                    if (isnan(a) && isnan(b)) continue;
                    if (fmode == 2) { if (fabs(a - b) > 1e-9 * (fabs(b) + 1e-300) && !(isinf(a) && a == b)) badfp = 1; }
                    else if (a != b && !(a == 0 && b == 0)) badfp = 1;
                }
                if (((fsw >> 11) & 7) != (R->ftop & 7)) badfp = 1;
                if ((fsw ^ fstsw(R)) & 0x4500) badfp = 1;
                bad |= badfp;
            }
            total++;
            if (bad) {
                fails++;
                if (!case_fail) {
                    failed_cases++;
                    char a[8], b[8], c0[8];
                    dump_flags(flags, c0); dump_flags(gfl, a); dump_flags(ofl, b);
                    printf("FAIL [%s]\n  in : eax=%08x ecx=%08x edx=%08x ebx=%08x esp=%08x ebp=%08x esi=%08x edi=%08x fl=%s\n",
                           fz_text[tid], regs[0], regs[1], regs[2], regs[3], regs[4], regs[5], regs[6], regs[7], c0);
                    printf("  ref: eax=%08x ecx=%08x edx=%08x ebx=%08x esp=%08x ebp=%08x esi=%08x edi=%08x fl=%s taken=%u\n",
                           out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7], b, tk);
                    printf("  c  : eax=%08x ecx=%08x edx=%08x ebx=%08x esp=%08x ebp=%08x esi=%08x edi=%08x fl=%s taken=%d mask=%x%s\n",
                           got[0], got[1], got[2], got[3], got[4], got[5], got[6], got[7], a, taken, mask, badmem ? " MEM" : "");
                    if (badfp) {
                        printf("  fpu: top ref=%u c=%u  sw ref=%04x c=%04x\n", (fsw >> 11) & 7, R->ftop, fsw & 0x4700, fstsw(R) & 0x4700);
                        for (int i = 0; i < 8; i++) if (R->st[i] != fout[i]) printf("    st[%d] in=%.17g ref=%.17g c=%.17g\n", i, fst[i], fout[i], R->st[i]);
                    }
                }
                case_fail = 1;
            }
            free(wa); free(wb);
        }
    }
    printf("runs %d, failures %d, failing cases %d of %u\n", total, fails, failed_cases, ncases);
    return fails != 0;
}
